import random, time
from datetime import datetime, timezone

RETRYABLE = {429, 500, 502, 503, 504}

def send_update(session, tracking_id, token, max_tries=4):
    body = {"tracking_id": tracking_id, "status": "DELIVERED",
            "occurred_at": datetime.now(timezone.utc).isoformat()}   # ends in +00:00
    headers = {"Authorization": f"Bearer {token}",
               "Idempotency-Key": f"{tracking_id}-DELIVERED"}       # resending is safe
    for attempt in range(1, max_tries + 1):
        resp = session.post("https://api.partner.example/v2/deliveries",
                            json=body, headers=headers, timeout=10)  # json= sets Content-Type
        if resp.status_code in (200, 201):
            return "sent"
        if resp.status_code not in RETRYABLE:                      # 4xx: our request is wrong
            return f"alert: {resp.status_code} {resp.text[:200]}"
        wait = float(resp.headers.get("Retry-After", 2 ** attempt)) + random.random()
        time.sleep(min(wait, 30))                                  # back off, with jitter
    return "gave up: queued for the replay job"

class FakeResp:        # stand-ins so the logic is testable without the partner API;
    def __init__(self, code, text=""):             # production passes requests.Session()
        self.status_code, self.text, self.headers = code, text, {"Retry-After": "0"}

class FakeSession:
    def __init__(self, codes): self.codes = list(codes)
    def post(self, url, **kwargs): return FakeResp(self.codes.pop(0), "occurred_at: missing offset")

print(send_update(FakeSession([503, 201]), "BW-1001", "token"))   # sent
print(send_update(FakeSession([422]), "BW-1002", "token"))        # alert: 422 ...

CREATE TABLE accounts (
  account_id      bigint PRIMARY KEY,
  balance         numeric(12,2) NOT NULL,
  overdraft_limit numeric(12,2) NOT NULL DEFAULT 0,
  CHECK (balance >= -overdraft_limit)          -- enforced for every client, not just ours
);
CREATE TABLE transfers (
  idempotency_key text PRIMARY KEY,            -- a retried request cannot run twice
  from_acct bigint NOT NULL REFERENCES accounts,
  to_acct   bigint NOT NULL REFERENCES accounts,
  amount    numeric(12,2) NOT NULL CHECK (amount > 0)
);

CREATE FUNCTION transfer(p_key text, p_from bigint, p_to bigint, p_amount numeric)
RETURNS text LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO transfers VALUES (p_key, p_from, p_to, p_amount) ON CONFLICT DO NOTHING;
  IF NOT FOUND THEN RETURN 'duplicate: already done'; END IF;
  PERFORM 1 FROM accounts WHERE account_id IN (p_from, p_to)
    ORDER BY account_id FOR UPDATE;            -- lower id first, always: no deadlocks
  UPDATE accounts SET balance = balance - p_amount WHERE account_id = p_from;
  UPDATE accounts SET balance = balance + p_amount WHERE account_id = p_to;
  RETURN 'done';
END $$;

-- The service runs:  BEGIN; SELECT transfer('tr_8f2c1a', 1042, 2213, 250.00); COMMIT;
-- Any error before COMMIT (a crash, or the CHECK failing) rolls back all three changes.

