import re
EMAIL = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")

def find_duplicates(customers):
    """O(n): one pass, one dict lookup per customer."""
    first_seen, dupes, rejected = {}, [], []
    for c in customers:
        email = (c.get("email") or "").strip().lower()
        if not EMAIL.match(email):
            rejected.append(c)            # defensive: keep, do not crash
            continue
        key = (email, c.get("postcode", "").replace(" ", "").upper())
        if key in first_seen:
            dupes.append((first_seen[key], c["id"]))
        else:
            first_seen[key] = c["id"]
    return dupes, rejected

import random, time, requests

RETRYABLE = {429, 500, 502, 503, 504}

def get_page(url, params, max_tries=6):
    for attempt in range(max_tries):
        try:
            r = requests.get(url, params=params, timeout=15)
        except requests.Timeout:
            r = None
        if r is not None and r.status_code == 200:
            return r.json()
        if r is not None and r.status_code not in RETRYABLE:
            r.raise_for_status()               # 4xx: our bug, fail loudly
        wait = float(r.headers.get("Retry-After", 0)) if r is not None else 0
        wait = max(wait, 2 ** attempt + random.uniform(0, 1))
        time.sleep(wait)
    raise RuntimeError(f"gave up after {max_tries} tries: {url}")

