// app.js: calls our own backend, never the model provider directly
const btn = document.querySelector('#triage');
const out = document.querySelector('#result');

btn.addEventListener('click', async () => {
  const text = document.querySelector('#claim').value.trim();
  if (!text) { out.textContent = 'Paste a claim first.'; return; }
  btn.disabled = true;
  out.textContent = 'Working...';
  try {
    const res = await fetch('/triage', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ claim_text: text })
    });
    if (!res.ok) throw new Error('Server returned ' + res.status);
    const data = await res.json();
    out.innerHTML = '';
    out.append(`Priority: ${data.priority}\n${data.summary}`);
  } catch (err) {
    out.textContent = 'Could not triage this claim. Try again or triage manually.';
  } finally {
    btn.disabled = false;
  }
});

import re, heapq
from collections import defaultdict

def norm_key(m: dict) -> str:
    if m.get("vat"):
        return "VAT:" + m["vat"].replace(" ", "").upper()
    name = re.sub(r"\b(b\.?v\.?|ltd|gmbh)\b|[^a-z0-9]", "", m["name"].lower())
    return f"NP:{name}:{m['postcode'].replace(' ', '').upper()}"

def duplicate_groups(merchants: list[dict]) -> dict[str, list[str]]:
    groups = defaultdict(list)           # one pass, O(n)
    for m in merchants:
        groups[norm_key(m)].append(m["id"])
    return {k: ids for k, ids in groups.items() if len(ids) > 1}

def biggest(groups: dict, k: int = 200):
    return heapq.nlargest(k, groups.items(), key=lambda kv: len(kv[1]))
